use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input["text"].as_str().unwrap();
    let pattern = input["pattern"].as_str().unwrap();
    let mut result = Vec::new();
    let mut start = 0;
    let mut pos = 0;
    while let Some(c) = text.chars().nth(pos) {
        if c == pattern.chars().nth(pos).unwrap() {
            pos += 1;
            if pos == pattern.len() {
                result.push(start);
                start = pos;
            }
        } else {
            pos = 0;
        }
    }
    Value::Array(result.into_iter().map(|i| Value::Number(i as f64)).collect())
}
